/// Возвращает растровый срез глифа для символа Unicode.
/// Частые диапазоны (ASCII, кириллица, латиница, псевдографика) индексируются за O(1),
/// остальные символы находятся бинарным поиском за <= 10 шагов.
pub fn get_glyph(ch: char) -> Option<&'static [u16; 20]> {
    let cp = ch as u32;
    match cp {
        0x20..=0x7E => Some(&ASCII_GLYPHS[(cp - 0x20) as usize]),
        0x00A0..=0x00FF => Some(&LATIN_SUPPL_GLYPHS[(cp - 0x00A0) as usize]),
        0x0400..=0x045F => Some(&CYRILLIC_GLYPHS[(cp - 0x0400) as usize]),
        0x2500..=0x257F => Some(&BOX_DRAWING_GLYPHS[(cp - 0x2500) as usize]),
        0x2580..=0x259F => Some(&BLOCK_ELEMENTS_GLYPHS[(cp - 0x2580) as usize]),
        _ => {
            if let Ok(idx) = EXTRA_GLYPHS.binary_search_by_key(&cp, |&(code, _)| code) {
                Some(&EXTRA_GLYPHS[idx].1)
            } else {
                None
            }
        }
    }
}

pub fn draw_char(
    fb: &mut Framebuffer,
    x: usize,
    y: usize,
    ch: char,
    color: u32,
    bg_color: u32,
) {
    let glyph = get_glyph(ch).unwrap_or(&REPLACEMENT_GLYPH);

    // Честный растр 10x20: старший бит 15 соответствует x + 0
    for (row_idx, &row_word) in glyph.iter().enumerate() {
        let py = y + row_idx;
        for col_idx in 0..10 {
            let px = x + col_idx;
            let is_fg = (row_word & (0x8000 >> col_idx)) != 0;
            let pixel_color = if is_fg { color } else { bg_color };
            fb.put_pixel(px, py, pixel_color);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test_case]
    fn test_font_glyph_lookup() {
        // ASCII
        assert!(get_glyph('A').is_some());
        assert!(get_glyph(' ').is_some());
        assert!(get_glyph('~').is_some());
        assert!(get_glyph('0').is_some());
        assert!(get_glyph('1').is_some());

        // Кириллица (русский, украинский, белорусский)
        assert!(get_glyph('А').is_some());
        assert!(get_glyph('я').is_some());
        assert!(get_glyph('Ё').is_some());
        assert!(get_glyph('ё').is_some());
        assert!(get_glyph('І').is_some());
        assert!(get_glyph('і').is_some());
        assert!(get_glyph('Ї').is_some());
        assert!(get_glyph('ї').is_some());
        assert!(get_glyph('Є').is_some());
        assert!(get_glyph('є').is_some());
        assert!(get_glyph('Ў').is_some());
        assert!(get_glyph('ў').is_some());
        assert!(get_glyph('Ґ').is_some());
        assert!(get_glyph('ґ').is_some());
        assert!(get_glyph('№').is_some());

        // Псевдографика (Box Drawing)
        assert!(get_glyph('─').is_some());
        assert!(get_glyph('│').is_some());
        assert!(get_glyph('┌').is_some());
        assert!(get_glyph('┐').is_some());
        assert!(get_glyph('└').is_some());
        assert!(get_glyph('┘').is_some());
        assert!(get_glyph('├').is_some());
        assert!(get_glyph('┤').is_some());
        assert!(get_glyph('┬').is_some());
        assert!(get_glyph('┴').is_some());
        assert!(get_glyph('┼').is_some());
        assert!(get_glyph('═').is_some());
        assert!(get_glyph('║').is_some());
        assert!(get_glyph('╔').is_some());
        assert!(get_glyph('╗').is_some());
        assert!(get_glyph('╚').is_some());
        assert!(get_glyph('╝').is_some());

        // Блочные элементы (Block Elements)
        assert!(get_glyph('█').is_some());
        assert!(get_glyph('▀').is_some());
        assert!(get_glyph('▄').is_some());
        assert!(get_glyph('▌').is_some());
        assert!(get_glyph('▐').is_some());
        assert!(get_glyph('░').is_some());
        assert!(get_glyph('▒').is_some());
        assert!(get_glyph('▓').is_some());

        // Символы, валюты, стрелки и математика
        assert!(get_glyph('₽').is_some());
        assert!(get_glyph('€').is_some());
        assert!(get_glyph('←').is_some());
        assert!(get_glyph('→').is_some());
        assert!(get_glyph('↑').is_some());
        assert!(get_glyph('↓').is_some());
        assert!(get_glyph('≠').is_some());
        assert!(get_glyph('≤').is_some());
        assert!(get_glyph('≥').is_some());
        assert!(get_glyph('√').is_some());
        assert!(get_glyph('∞').is_some());
        assert!(get_glyph('✓').is_some());
        assert!(get_glyph('★').is_some());
        assert!(get_glyph('☆').is_some());
        assert!(get_glyph('♥').is_some());

        // Непечатаемые / недопустимые символы
        assert!(get_glyph('\0').is_none());
        assert!(get_glyph('\u{E000}').is_none());
    }

    #[test_case]
    fn test_box_drawing_continuity() {
        // Горизонтальная линия обязана быть непрерывной по всей ширине (10 бит = 0xFFC0)
        let h_line = get_glyph('─').unwrap();
        assert_eq!(h_line[9], 0xFFC0);
        assert_eq!(h_line[10], 0xFFC0);

        // Полный блок обязан заполнять все знакоместо целиком
        let full_block = get_glyph('█').unwrap();
        for &row in full_block.iter() {
            assert_eq!(row, 0xFFC0);
        }
    }
}
